import sys
a = sys.argv[sys.argv.index('--action') + 1]
if a == 'ok':
    print('{"allowed": true, "action": "ok", "reason_codes": []}')
elif a == 'deny':
    sys.stdout.write('{"allowed": false, "reason_codes": ["X"]}')
    sys.exit(3)
elif a == 'deny0':
    print('{"allowed": false}')
elif a == 'notdict':
    print('[1]')
else:
    print('not json')
    sys.stderr.write('  boom  \n')
    sys.exit(4)

#!/bin/bash
while [ $# -gt 0 ]; do if [ "$1" = --action ]; then a=$2; fi; shift; done
case "$a" in
 ok) echo '{"allowed": true, "action": "ok", "reason_codes": []}';;
 deny) printf '%s' '{"allowed": false, "reason_codes": ["X"]}'; exit 3;;
 deny0) echo '{"allowed": false}';;
 notdict) echo '[1]';;
 *) echo 'not json'; printf '  boom  \n' >&2; exit 4;;
esac

